char* EncodeVarint32(char* dst, uint32_t v) {
    // Fast path for small values (fits in 1 byte)
    if (v < (1 << 7)) {
        *(reinterpret_cast<unsigned char*>(dst)) = static_cast<unsigned char>(v);
        return dst + 1;
    }
    // General case: encode up to 5 bytes
    unsigned char* ptr = reinterpret_cast<unsigned char*>(dst);
    static const int B = 128;
    if (v < (1 << 14)) {
        ptr[0] = static_cast<unsigned char>(v | B);
        ptr[1] = static_cast<unsigned char>(v >> 7);
        return dst + 2;
    } else if (v < (1 << 21)) {
        ptr[0] = static_cast<unsigned char>(v | B);
        ptr[1] = static_cast<unsigned char>((v >> 7) | B);
        ptr[2] = static_cast<unsigned char>(v >> 14);
        return dst + 3;
    } else if (v < (1 << 28)) {
        ptr[0] = static_cast<unsigned char>(v | B);
        ptr[1] = static_cast<unsigned char>((v >> 7) | B);
        ptr[2] = static_cast<unsigned char>((v >> 14) | B);
        ptr[3] = static_cast<unsigned char>(v >> 21);
        return dst + 4;
    } else {
        ptr[0] = static_cast<unsigned char>(v | B);
        ptr[1] = static_cast<unsigned char>((v >> 7) | B);
        ptr[2] = static_cast<unsigned char>((v >> 14) | B);
        ptr[3] = static_cast<unsigned char>((v >> 21) | B);
        ptr[4] = static_cast<unsigned char>(v >> 28);
        return dst + 5;
    }
}

// Test cases
int main() {
    char buffer[10];
    // Test small value
    char* p = EncodeVarint32(buffer, 123);
    // Test medium value
    p = EncodeVarint32(buffer, 16383);
    // Test large value
    p = EncodeVarint32(buffer, 2147483647);
    return 0;
}

